                                  <div className="flex justify-end gap-1">
                                    <Link
                                      to={`/products/edit/${product.id}`}
                                      className="p-1.5 text-blue-500 hover:bg-blue-100 rounded-lg transition-colors"
                                    >
                                      <Pencil size={14} />
                                    </Link>
                                    <button
                                      onClick={() => {
                                        if (confirm("Видалити цей товар?")) {
