import React, { useEffect, useState } from "react";
import { ApiService } from "../services/api";
import { DashboardStats, Order, Product } from "../types";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from "recharts";
import { DollarSign, ShoppingBag, Package, AlertTriangle } from "lucide-react";

const getProductCategories = (value?: string) => {
  if (!value) return [];
  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
};

const StatCard = ({ title, value, icon: Icon, color, subtext }: any) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
    <div className="flex items-center justify-between">
      <div>
        <p className="text-sm font-medium text-gray-500">{title}</p>
        <h3 className="text-2xl font-bold mt-1 text-gray-900">{value}</h3>
      </div>
      <div className={`p-3 rounded-full ${color}`}>
        <Icon size={24} className="text-white" />
      </div>
    </div>
    {subtext && <p className="text-xs text-gray-400 mt-4">{subtext}</p>}
  </div>
);

export const Dashboard: React.FC = () => {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [orders, setOrders] = useState<Order[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      try {
        const [ordersData, productsData] = await Promise.all([
          ApiService.getOrders(),
          ApiService.getProducts(),
        ]);

        const totalRevenue = ordersData.reduce(
          (acc, order) => acc + (order.totalUAH ?? 0),
          0,
        );
        const pending = ordersData.filter((o) => o.status === "new").length;
        // Mock stock logic since backend doesn't track quantity yet, assume inStock=true is > 0
        const lowStock = productsData.filter((p) => !p.inStock).length;

        setStats({
          totalRevenue,
          totalOrders: ordersData.length,
          pendingOrders: pending,
          lowStockItems: lowStock,
        });
        setOrders(
          ordersData.sort(
            (a, b) =>
              new Date(b.created_at).getTime() -
              new Date(a.created_at).getTime(),
          ),
        );
        setProducts(productsData);
      } catch (error) {
        console.error("Failed to load dashboard data");
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  if (loading || !stats) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  // Calculate Sales by Category
  const salesByCategories = Array.from(
    new Set(products.flatMap((p) => getProductCategories(p.category))),
  ).map((categoryName: string) => {
    const categoryProducts = products
      .filter((p) => getProductCategories(p.category).includes(categoryName))
      .map((p) => p.id);
    const count = orders.reduce((acc, order) => {
      const categoryItems = order.items.filter((item) =>
        categoryProducts.includes(item.product_id),
      );
      return acc + categoryItems.reduce((sum, item) => sum + item.quantity, 0);
    }, 0);
    return { name: categoryName, value: count };
  });

  return (
    <div className="space-y-6">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard
          title="Загальний Дохід"
          value={`${stats.totalRevenue.toLocaleString()} ₴`}
          icon={DollarSign}
          color="bg-emerald-500"
          subtext="За весь час"
        />
        <StatCard
          title="Всього Замовлень"
          value={stats.totalOrders}
          icon={ShoppingBag}
          color="bg-blue-600"
          subtext="Оброблено"
        />
        <StatCard
          title="Нові Замовлення"
          value={stats.pendingOrders}
          icon={Package}
          color="bg-amber-500"
          subtext="Потребують уваги"
        />
        <StatCard
          title="Немає в наявності"
          value={stats.lowStockItems}
          icon={AlertTriangle}
          color="bg-slate-700"
          subtext="Товари не в наявності"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Chart 1: Sales by Category */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-slate-900 mb-4">
            Продажі за категоріями (шт)
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={salesByCategories}>
                <CartesianGrid
                  strokeDasharray="3 3"
                  vertical={false}
                  stroke="#f1f5f9"
                />
                <XAxis
                  dataKey="name"
                  axisLine={false}
                  tickLine={false}
                  tick={{ fill: "#94a3b8", fontSize: 12 }}
                  dy={10}
                />
                <YAxis
                  axisLine={false}
                  tickLine={false}
                  tick={{ fill: "#94a3b8", fontSize: 12 }}
                />
                <Tooltip
                  cursor={{ fill: "#f8fafc" }}
                  contentStyle={{
                    backgroundColor: "#fff",
                    borderRadius: "12px",
                    border: "none",
                    boxShadow: "0 10px 15px -3px rgb(0 0 0 / 0.1)",
                  }}
                  itemStyle={{ color: "#1e293b", fontWeight: "bold" }}
                />
                <Bar
                  dataKey="value"
                  fill="#4169E1"
                  radius={[6, 6, 0, 0]}
                  barSize={40}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Chart 2: Order Status Distribution */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-slate-900 mb-4">
            Статус Замовлень
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={[
                    { name: "Нові", value: stats.pendingOrders },
                    {
                      name: "Завершені",
                      value: stats.totalOrders - stats.pendingOrders,
                    },
                  ]}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={85}
                  paddingAngle={8}
                  dataKey="value"
                >
                  <Cell fill="#f59e0b" stroke="none" />
                  <Cell fill="#10b981" stroke="none" />
                </Pie>
                <Tooltip
                  contentStyle={{
                    borderRadius: "12px",
                    border: "none",
                    boxShadow: "0 10px 15px -3px rgb(0 0 0 / 0.1)",
                  }}
                />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex justify-center gap-6 mt-2">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-amber-500"></div>
                <span className="text-xs font-bold text-slate-600 uppercase tracking-tight">
                  Нові
                </span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-emerald-500"></div>
                <span className="text-xs font-bold text-slate-600 uppercase tracking-tight">
                  Завершені
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

