  const { login } = useAuth();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await login(username, password);
      navigate("/");
    } catch (err: any) {
      console.error("Login failed:", err);
      setError(
        err.message || "Помилка входу. Перевірте ім'я користувача та пароль.",
